import json
def transform(g):
    h=len(g); w=len(g[0])
    c=g[h//2][w//2]
    rh=[1 if c in row else 2 for row in g]
    cw=[1 if c in [g[i][j] for i in range(h)] else 2 for j in range(w)]
    out=[]
    for i,row in enumerate(g):
        orow=[]
        for j,v in enumerate(row): orrow=None; orow+=[v]*cw[j]
        for _ in range(rh[i]): out.append(orow[:])
    return out
